const e={preflight:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Eine schnelle Nur-Lese-Prüfung, ob der Drucker bereit ist, einen Druck zu starten."}},refresh:{t:0,b:{t:2,i:[{t:3}],s:"Erneut prüfen"}},checking:{t:0,b:{t:2,i:[{t:3}],s:"Wird geprüft …"}},ready:{t:0,b:{t:2,i:[{t:3}],s:"Druckbereit"}},notReady:{t:0,b:{t:2,i:[{t:3}],s:"Nicht druckbereit"}},checks:{unreachable:{fail:{t:0,b:{t:2,i:[{t:3}],s:"Drucker ist nicht erreichbar"}}},klippy:{pass:{t:0,b:{t:2,i:[{t:3}],s:"Klipper ist bereit"}},fail:{t:0,b:{t:2,i:[{t:3,v:"Klipper ist nicht bereit (Status: "},{t:4,k:"state"},{t:3,v:")"}]}}},idle:{pass:{t:0,b:{t:2,i:[{t:3}],s:"Kein Druck läuft"}},fail:{t:0,b:{t:2,i:[{t:3,v:"Es läuft bereits ein Druck ("},{t:4,k:"state"},{t:3,v:")"}]}}},homed:{pass:{t:0,b:{t:2,i:[{t:3}],s:"Alle Achsen sind referenziert"}},fail:{t:0,b:{t:2,i:[{t:3,v:"Achsen nicht referenziert ("},{t:4,k:"axes"},{t:3,v:"); ein Druckstart führt üblicherweise zuerst eine Referenzfahrt aus"}]}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"Anleitung"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"Anleitung zur Vor-Druck-Prüfung"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Schließen"}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:"Was ist die Vor-Druck-Prüfung?"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Ein Nur-Lese-Blick darauf, ob der Drucker startbereit ist: Es wird nichts bewegt oder verändert, es wird nur berichtet. Harte Blocker färben das Urteil rot; Warnungen informieren, blockieren aber nicht."}}},checks:{title:{t:0,b:{t:2,i:[{t:3}],s:"Was geprüft wird"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Ob Klipper bereit ist (nicht heruntergefahren oder im Fehlerzustand), ob nicht bereits ein Druck läuft und ob die Achsen referenziert sind (informativ, da ein Druckstart üblicherweise zuerst eine Referenzfahrt ausführt)."}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"Glossar"}}}},glossary:{klippyState:{term:{t:0,b:{t:2,i:[{t:3}],s:"Klipper-Status"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Klippers eigener Status - 'ready' bedeutet, es ist verbunden und im Leerlauf; 'shutdown' oder 'error' bedeutet, es kann erst drucken, wenn der Zustand behoben ist."}}},homing:{term:{t:0,b:{t:2,i:[{t:3}],s:"Referenzfahrt (Homing)"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Jede Achse wird zu ihrem Endschalter (Endstop) gefahren, damit der Drucker weiß, wo sich der Werkzeugkopf befindet. Die meisten Druckstart-Routinen führen die Referenzfahrt automatisch aus."}}}}}}};export{e as default};
